-- BAS Intelligence schema. Portable between PostgreSQL 15+ (Neon) and H2 in PostgreSQL mode.
-- UUID keys are generated by the application (java.util.UUID) so no database-specific default is needed.

CREATE TABLE factories (
    id          UUID PRIMARY KEY,
    code        VARCHAR(40)  NOT NULL UNIQUE,
    name        VARCHAR(120) NOT NULL,
    location    VARCHAR(200),
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()
);

CREATE TABLE users (
    id              UUID PRIMARY KEY,
    username        VARCHAR(80)  NOT NULL UNIQUE,
    password_hash   VARCHAR(100) NOT NULL,
    roles           VARCHAR(200) NOT NULL,
    enabled         BOOLEAN NOT NULL DEFAULT TRUE,
    factory_id      UUID REFERENCES factories (id),
    created_at      TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    CONSTRAINT ck_users_username CHECK (LENGTH(username) >= 3)
);
